    const onDraftChange = (next: AutomationDetail) => {
        setDraft(next);
        setEditState((prev) => {
            if (prev === 'failed to save' || prev === 'failed to publish' || prev === 'failed to unpublish') {
                return 'idle';
            }
            return prev;
        });
    };

